"use client";

import { useEffect, useRef, useState } from "react";
import { REJECT_REASONS } from "@/lib/pipeline/profiles";
import { initials, useUser } from "@/lib/user";
import type { FeatureRequest } from "@/lib/pipeline/types";

/** Modal asking why a request is rejected. A reason is required; it is saved as a decision. */
export function RejectDialog({
  request,
  onCancel,
  onConfirm,
}: {
  request: FeatureRequest | null;
  onCancel: () => void;
  onConfirm: (reason: string) => void;
}) {
  const ref = useRef<HTMLDialogElement>(null);
  const user = useUser();
  const [preset, setPreset] = useState<string | null>(null);
  const [note, setNote] = useState("");

  useEffect(() => {
    const d = ref.current;
    if (!d) return;
    if (request && !d.open) {
      setPreset(null);
      setNote("");
      d.showModal();
    } else if (!request && d.open) d.close();
  }, [request]);

  const reason = [preset, note.trim()].filter(Boolean).join(": ");
  const valid = preset !== null || note.trim().length >= 3;

  return (
    <dialog
      ref={ref}
      onCancel={(e) => {
        e.preventDefault();
        onCancel();
      }}
      aria-labelledby="reject-title"
      className="m-auto w-[min(520px,calc(100vw-32px))] rounded-card border border-line bg-surface p-0 text-ink shadow-float backdrop:bg-ink/30 backdrop:backdrop-blur-[2px]"
    >
      {request && (
        <form
          method="dialog"
          onSubmit={(e) => {
            e.preventDefault();
            if (valid) onConfirm(reason);
          }}
          className="flex flex-col gap-4 p-5 sm:p-6"
        >
          <div>
            <p className="text-xs font-semibold uppercase tracking-[0.12em] text-human">Reject request</p>
            <h2 id="reject-title" className="mt-1 text-lg font-semibold tracking-tight">
              Why are you rejecting “{request.title}”?
            </h2>
            <p className="mt-1 text-sm text-muted">
              Your reason is saved in Decisions and shows on every profile this request could have shaped.
            </p>
            <p className="mt-2 inline-flex items-center gap-2 rounded-full bg-bg-soft py-1 pl-1 pr-3 text-xs text-ink-soft ring-1 ring-line">
              <span className="flex size-5 items-center justify-center rounded-full bg-ink text-[0.6rem] font-semibold text-white">{initials(user.name)}</span>
              Recorded as <span className="font-medium text-ink">{user.name}</span> · {user.role} · now
            </p>
          </div>

          <fieldset>
            <legend className="sr-only">Common reasons</legend>
            <div className="flex flex-wrap gap-2">
              {REJECT_REASONS.map((r) => {
                const on = preset === r;
                return (
                  <button
                    key={r}
                    type="button"
                    aria-pressed={on}
                    onClick={() => setPreset(on ? null : r)}
                    className={`rounded-full px-3 py-1.5 text-sm transition-colors duration-150 motion-reduce:transition-none ${
                      on ? "bg-human text-white" : "bg-bg-soft text-ink-soft ring-1 ring-line hover:ring-human/40"
                    }`}
                  >
                    {r}
                  </button>
                );
              })}
            </div>
          </fieldset>

          <label className="flex flex-col gap-1.5 text-sm">
            <span className="font-medium text-ink">Explain in your words {preset ? <span className="font-normal text-muted">(optional)</span> : <span className="font-normal text-human">(required)</span>}</span>
            <textarea
              value={note}
              onChange={(e) => setNote(e.target.value)}
              rows={3}
              autoFocus
              placeholder="e.g. Our principle P1 says the car stays compact; this would add 8 cm."
              className="resize-y rounded-lg border border-line bg-surface px-3 py-2 text-sm text-ink placeholder:text-muted/70 focus:border-brand focus:outline-none"
            />
          </label>

          <div className="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
            <button type="button" onClick={onCancel} className="h-10 rounded-full px-4 text-sm font-medium text-ink-soft ring-1 ring-line hover:bg-bg-soft">
              Cancel
            </button>
            <button
              type="submit"
              disabled={!valid}
              className="h-10 rounded-full bg-human px-5 text-sm font-medium text-white shadow-card transition-opacity disabled:cursor-not-allowed disabled:opacity-40"
            >
              Reject and save reason
            </button>
          </div>
        </form>
      )}
    </dialog>
  );
}
import type { Decisions } from "@/lib/pipeline/profiles";

/** Every keep / reject (with reason) / wishlist decision, newest first. `full` drops the scroll cap. */
export function DecisionLog({ decisions, full }: { decisions: Decisions; full?: boolean }) {
  const list = Object.values(decisions).sort((a, b) => b.at.localeCompare(a.at));
  return (
    <section className="rounded-card border border-line bg-surface shadow-card">
      <h2 className="border-b border-line px-4 py-3 text-sm font-semibold text-ink">Decisions</h2>
      {list.length === 0 ? (
        <p className="px-4 py-4 text-sm text-muted">Nothing decided yet. Keep or reject requests; each decision is logged here with its reason.</p>
      ) : (
        <ul className={`divide-y divide-line ${full ? "" : "max-h-80 overflow-y-auto"}`}>
          {list.map((d) => (
            <li key={d.requestId} className="px-4 py-3 text-sm">
              <p className="flex items-center gap-1.5">
                <span className={`text-xs font-semibold ${d.action === "keep" ? "text-good" : d.action === "wish" ? "text-brand" : "text-bad"}`}>
                  {d.action === "keep" ? "Kept" : d.action === "wish" ? "Wishlist" : "Rejected"}
                </span>
                <span className="truncate font-medium text-ink">{d.title}</span>
              </p>
              {d.reason && <p className="mt-0.5 text-ink-soft">“{d.reason}”</p>}
              <p className="mt-0.5 text-xs text-muted">
                <span className="font-medium text-ink-soft">{d.by}</span>
                {d.role && ` (${d.role})`} · {new Date(d.at).toLocaleString("en-GB", { dateStyle: "medium", timeStyle: "short" })}
              </p>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}
/* Generations (stored as sessions): every "Build profiles" saves a snapshot, so a PM can reopen earlier generations later.
 * Stored in this browser for now (localStorage); moves to Supabase with the backend.
 */
import type { MarketScope } from "@/lib/dashboard-data";
import type { Campaign } from "./analytics";
import type { Decisions, Profile } from "./profiles";
import type { SeriesId } from "./types";

export interface Session {
  id: string;
  createdAt: string;
  /** Who built this generation. */
  createdBy?: string;
  createdByRole?: string;
  scope: MarketScope;
  scopeLabel: string;
  series: SeriesId;
  seriesName: string;
  slug: string;
  profiles: Profile[];
  decisions: Decisions;
  order: string[];
  campaigns: Campaign[] | null;
}

const KEY = "dixi:sessions";
const MAX = 30;

export function readSessions(): Session[] {
  try {
    return (JSON.parse(localStorage.getItem(KEY) ?? "[]") as Session[]).sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  } catch {
    return [];
  }
}

function write(list: Session[]) {
  try {
    localStorage.setItem(KEY, JSON.stringify(list.slice(0, MAX)));
  } catch {
    /* storage full or blocked: sessions stay for this visit only */
  }
}

export function saveSession(s: Session) {
  write([s, ...readSessions().filter((x) => x.id !== s.id)]);
}

export function updateSession(id: string, patch: Partial<Session>) {
  write(readSessions().map((s) => (s.id === id ? { ...s, ...patch } : s)));
}

export function deleteSession(id: string) {
  write(readSessions().filter((s) => s.id !== id));
}

export const newSessionId = () => `G-${Date.now().toString(36).toUpperCase()}`;

/** The generation's own dashboard. */
export const generationHref = (id: string) => `/dashboard/generations#${id}`;
/** Back into the pipeline with this generation's decisions and priority loaded, to edit and rebuild. */
export const editHref = (s: Pick<Session, "scope" | "slug" | "id">) => `/dashboard/${s.scope.toLowerCase()}/${s.slug}#session=${s.id}`;

export const sessionTime = (iso: string) => new Date(iso).toLocaleString("en-GB", { dateStyle: "medium", timeStyle: "short" });
