// Offline check of the demo data against the app's own scoring + profile logic.
// Run from _tools: npx tsx sim.ts
import fs from "node:fs";
import { MARKET_SIGNALS } from "../../../web/src/lib/pipeline/market-signals";
import { buildProfiles, scopedMentions, signalsFor, urgencyOf } from "../../../web/src/lib/pipeline/profiles";
import { DEFAULT_SCORING, scoreRequest } from "../../../web/src/lib/pipeline/scoring";
import { seriesById } from "../../../web/src/lib/pipeline/series";

const data = JSON.parse(fs.readFileSync(new URL("../../02-data/demo-pipeline.json", import.meta.url), "utf-8"));
const g = data.series.find((s: any) => s.id === "G60");
const cfg = seriesById("G60");
const keepArg: Record<string, string[]> = JSON.parse(process.argv[2] ?? "{}");

for (const scope of ["CN", "US"] as const) {
  const signals = signalsFor(MARKET_SIGNALS, "G60", scope);
  const byTitle = new Map<string, number>();
  signals.forEach((s) => s.relatesTo.forEach((t) => byTitle.set(t, (byTitle.get(t) ?? 0) + 1)));
  const rows0 = g.requests.map((r: any) => ({ r, scoped: scopedMentions(r, scope, false) })).filter((x: any) => x.scoped > 0);
  const max = Math.max(...rows0.map((x: any) => x.scoped));
  const rows = rows0
    .map((x: any) => ({ ...x, s: scoreRequest(x.r, x.scoped, max, byTitle.get(x.r.title) ?? 0, cfg.focus, new Map(), DEFAULT_SCORING) }))
    .sort((a: any, b: any) => b.s.score - a.s.score || b.scoped - a.scoped);
  console.log(`\n== ${scope}: ${signals.length} signals, volume ${g.feedbackByMarket[scope]}`);
  rows.forEach((x: any, i: number) => console.log(`${i + 1}. ${x.r.title} · ${x.scoped} · score ${x.s.score} · ${urgencyOf(x.scoped)}`));
  const keep = keepArg[scope] ?? rows.slice(0, 3).map((x: any) => x.r.title);
  const kept = rows.filter((x: any) => keep.includes(x.r.title)).map((x: any) => x.r);
  const profiles = buildProfiles(kept, cfg, scope, false, null, [], signals);
  console.log(`-- profiles keeping ${keep.join(", ")}`);
  profiles.forEach((p) => console.log(`  ${p.name} total ${(p.score.total * 100).toFixed(1)} L1 ${(p.score.l1 * 100).toFixed(0)} L2 ${(p.score.l2 * 100).toFixed(0)} :: ${p.requests.map((r) => r.title).join(" / ")}`));
}

