// Shared helpers for the Dixi screen recordings: browser setup, visible cursor, human-speed input,
// CDP screencast capture (high-quality JPEG frames with timestamps) and event marks.
import fs from "node:fs";
import path from "node:path";
import { chromium } from "playwright";

export const BASE = process.env.DIXI_URL ?? "http://localhost:3000";
export const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), "..");
export const STILLS = path.join(ROOT, "stills");
export const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/* Cursor dot + click ripple, injected into every document. Position survives full navigations via sessionStorage. */
const CURSOR_JS = `(() => {
  if (window.__dixiCursor) return; window.__dixiCursor = true;
  const css = \`
    #__cur{position:fixed;left:0;top:0;width:22px;height:22px;margin:-11px 0 0 -11px;border-radius:50%;
      background:rgba(17,24,39,.55);border:2px solid rgba(255,255,255,.9);box-shadow:0 1px 6px rgba(0,0,0,.35);
      z-index:2147483647;pointer-events:none;transition:transform .12s ease, background .12s ease;}
    #__cur.down{transform:scale(.78);background:rgba(17,24,39,.75)}
    .__rip{position:fixed;width:22px;height:22px;margin:-11px 0 0 -11px;border-radius:50%;border:2px solid rgba(28,105,212,.85);
      z-index:2147483646;pointer-events:none;animation:__rip .55s ease-out forwards}
    @keyframes __rip{from{transform:scale(1);opacity:.95}to{transform:scale(3.2);opacity:0}}
    nextjs-portal{display:none!important}
  \`;
  const mount = () => {
    if (document.getElementById('__cur')) return;
    const st = document.createElement('style'); st.textContent = css; document.documentElement.appendChild(st);
    const c = document.createElement('div'); c.id = '__cur'; document.documentElement.appendChild(c);
    let p = null; try { p = JSON.parse(sessionStorage.getItem('__curpos') || 'null'); } catch {}
    if (p) { c.style.left = p.x + 'px'; c.style.top = p.y + 'px'; } else { c.style.left = '-50px'; c.style.top = '-50px'; }
    const move = (e) => { c.style.left = e.clientX + 'px'; c.style.top = e.clientY + 'px';
      try { sessionStorage.setItem('__curpos', JSON.stringify({ x: e.clientX, y: e.clientY })); } catch {} };
    window.addEventListener('pointermove', move, true);
    window.addEventListener('mousemove', move, true);
    window.addEventListener('pointerdown', (e) => { c.classList.add('down');
      const r = document.createElement('div'); r.className = '__rip'; r.style.left = e.clientX + 'px'; r.style.top = e.clientY + 'px';
      document.documentElement.appendChild(r); setTimeout(() => r.remove(), 600); }, true);
    window.addEventListener('pointerup', () => c.classList.remove('down'), true);
  };
  if (document.documentElement) mount(); else document.addEventListener('DOMContentLoaded', mount);
  // top-layer dialogs (<dialog>.showModal) paint above fixed elements: re-append the cursor into an open dialog
  const fix = () => { const c = document.getElementById('__cur'); if (!c) return;
    const d = [...document.querySelectorAll('dialog[open]')].pop();
    const host = d || document.documentElement; if (c.parentNode !== host) host.appendChild(c); };
  setInterval(fix, 50);
})();`;

export async function launch({ clear = true } = {}) {
  const browser = await chromium.launch({ channel: "chrome", headless: true, args: ["--hide-scrollbars", "--force-color-profile=srgb"] });
  const context = await browser.newContext({
    viewport: { width: 1920, height: 1080 },
    deviceScaleFactor: 1,
    colorScheme: "light",
    reducedMotion: "no-preference",
    locale: "en-GB",
  });
  await context.addInitScript(CURSOR_JS);
  const page = await context.newPage();
  page.on("console", (m) => m.type() === "error" && console.log("  [console]", m.text().slice(0, 200)));
  page.on("pageerror", (e) => console.log("  [pageerror]", e.message.slice(0, 200)));
  if (clear) {
    await page.goto(`${BASE}/dashboard/settings`);
    await page.evaluate(() => {
      Object.keys(localStorage).filter((k) => k.startsWith("dixi:")).forEach((k) => localStorage.removeItem(k));
      sessionStorage.clear();
    });
  }
  return { browser, context, page };
}

/* ---------- capture ---------- */
export class Recorder {
  constructor(page, name) {
    this.page = page;
    this.name = name;
    this.dir = path.join(ROOT, "_frames", name);
    fs.rmSync(this.dir, { recursive: true, force: true });
    fs.mkdirSync(this.dir, { recursive: true });
    this.frames = [];
    this.marks = [];
    this.writes = [];
  }
  async start() {
    this.cdp = await this.page.context().newCDPSession(this.page);
    this.cdp.on("Page.screencastFrame", (f) => {
      const file = path.join(this.dir, `f${String(this.frames.length).padStart(6, "0")}.jpg`);
      this.frames.push({ file, t: f.metadata.timestamp });
      this.writes.push(fs.promises.writeFile(file, Buffer.from(f.data, "base64")));
      this.cdp.send("Page.screencastFrameAck", { sessionId: f.sessionId }).catch(() => {});
    });
    await this.cdp.send("Page.startScreencast", { format: "jpeg", quality: 92, maxWidth: 1920, maxHeight: 1080, everyNthFrame: 1 });
    this.t0 = Date.now() / 1000;
    await sleep(300);
  }
  mark(label) {
    const t = Date.now() / 1000;
    this.marks.push({ label, t });
    console.log(`  mark ${(t - this.t0).toFixed(1).padStart(6)}s  ${label}`);
  }
  async stop() {
    await sleep(400);
    await this.cdp.send("Page.stopScreencast").catch(() => {});
    await Promise.all(this.writes);
    const tEnd = Date.now() / 1000;
    fs.writeFileSync(path.join(this.dir, "frames.json"), JSON.stringify({ frames: this.frames, marks: this.marks, t0: this.t0, tEnd }, null, 1));
    console.log(`  ${this.frames.length} frames, ${(tEnd - this.t0).toFixed(1)} s`);
  }
}

/* ---------- human-speed input ---------- */
export class Human {
  constructor(page) {
    this.page = page;
    this.x = 960;
    this.y = 600;
  }
  async moveTo(x, y, ms) {
    const dist = Math.hypot(x - this.x, y - this.y);
    const dur = ms ?? Math.min(1100, Math.max(350, dist * 0.9));
    const steps = Math.max(8, Math.round(dur / 16));
    const sx = this.x, sy = this.y;
    // slight arc so moves don't look robotic
    const nx = -(y - sy) / (dist || 1), ny = (x - sx) / (dist || 1);
    const bow = Math.min(60, dist * 0.08);
    for (let i = 1; i <= steps; i++) {
      const k = i / steps;
      const e = k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2;
      const arc = Math.sin(Math.PI * e) * bow;
      await this.page.mouse.move(sx + (x - sx) * e + nx * arc, sy + (y - sy) * e + ny * arc);
      await sleep(dur / steps);
    }
    this.x = x;
    this.y = y;
  }
  async box(locator) {
    await locator.waitFor({ state: "visible", timeout: 15000 });
    const b = await locator.boundingBox();
    if (!b) throw new Error("no bounding box");
    return b;
  }
  /** Scroll the element into view smoothly if it is off-screen, then move to it. */
  async hover(locator, { dx = 0, dy = 0, ms } = {}) {
    await this.ensureVisible(locator);
    const b = await this.box(locator);
    await this.moveTo(b.x + b.width / 2 + dx, b.y + b.height / 2 + dy, ms);
  }
  async click(locator, { pause = 750, after = 350, dx = 0, dy = 0 } = {}) {
    await this.hover(locator, { dx, dy });
    await sleep(pause);
    await this.page.mouse.down();
    await sleep(90);
    await this.page.mouse.up();
    await sleep(after);
  }
  async type(text, delay = 55) {
    for (const ch of text) {
      await this.page.keyboard.type(ch);
      await sleep(delay + Math.round((Math.random() - 0.5) * 24));
    }
  }
  async ensureVisible(locator, margin = 140) {
    const b = await this.box(locator);
    const vh = 1080 - 80; // fixed bottom bar on the pipeline
    if (b.y < 70 || b.y + b.height > vh) {
      const target = await this.page.evaluate(([y, h]) => window.scrollY + y - (window.innerHeight - h) / 2.6, [b.y, b.height]);
      await this.scrollTo(target);
    }
  }
  /** Smooth scroll to an absolute Y (requestAnimationFrame, ease-in-out). */
  async scrollTo(y, ms = 900) {
    await this.page.evaluate(
      ([to, dur]) =>
        new Promise((done) => {
          const from = window.scrollY;
          const max = document.documentElement.scrollHeight - window.innerHeight;
          const end = Math.max(0, Math.min(max, to));
          const t0 = performance.now();
          const step = (t) => {
            const k = Math.min(1, (t - t0) / dur);
            const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
            window.scrollTo(0, from + (end - from) * e);
            if (k < 1) requestAnimationFrame(step);
            else done();
          };
          requestAnimationFrame(step);
        }),
      [y, ms],
    );
    await sleep(120);
  }
  async scrollBy(dy, ms) {
    const y = await this.page.evaluate(() => window.scrollY);
    await this.scrollTo(y + dy, ms);
  }
}

export async function still(page, name) {
  fs.mkdirSync(STILLS, { recursive: true });
  await page.screenshot({ path: path.join(STILLS, name) });
  console.log(`  still ${name}`);
}

