      z-index:2147483647;pointer-events:none;transition:transform .12s ease, background .12s ease;}
    #__cur.down{transform:scale(.78);background:rgba(17,24,39,.75)}
    .__rip{position:fixed;width:22px;height:22px;margin:-11px 0 0 -11px;border-radius:50%;border:2px solid rgba(28,105,212,.85);
      z-index:2147483646;pointer-events:none;animation:__rip .55s ease-out forwards}
    @keyframes __rip{from{transform:scale(1);opacity:.95}to{transform:scale(3.2);opacity:0}}
    nextjs-portal{display:none!important}
