    const t1 = at(c.from) - (c.pre ?? 0);
    const t2 = c.to === "END" ? tEnd : at(c.to) + (c.post ?? 0);
    // last frame shown at or before t1, then every frame until t2
    let i0 = frames.findIndex((f) => f.t > t1) - 1;
    if (i0 < 0) i0 = 0;
    const sel = frames.slice(i0).filter((f, k) => k === 0 || f.t < t2);
    const lines = ["ffconcat version 1.0"];
    sel.forEach((f, k) => {
      const start = k === 0 ? t1 : f.t;
      const next = k + 1 < sel.length ? sel[k + 1].t : t2;
      lines.push(`file '${f.file}'`, `duration ${Math.max(0.001, next - start).toFixed(4)}`);
    });
    lines.push(`file '${sel[sel.length - 1].file}'`);
    const list = path.join(dir, `${path.basename(c.out, ".mp4")}.ffconcat`);
    fs.writeFileSync(list, lines.join("\n") + "\n");
    const out = path.join(ROOT, c.out);
    execFileSync(
      "ffmpeg",
      ["-y", "-loglevel", "error", "-f", "concat", "-safe", "0", "-i", list,
        "-vf", "scale=1920:1080:flags=lanczos,fps=30,format=yuv420p",
        "-c:v", "libx264", "-preset", "slow", "-crf", "16", "-tune", "stillimage", "-movflags", "+faststart", "-r", "30", "-t", (t2 - t1).toFixed(3), out],
      { stdio: "inherit" },
    );
    const inClip = marks.filter((m) => m.t >= t1 - 0.01 && m.t <= t2 + 0.01).map((m) => ({ s: +(m.t - t1).toFixed(1), label: m.label }));
    const dur = execFileSync("ffprobe", ["-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", out]).toString().trim();
    report.push({ out: c.out, duration: Number(dur), marks: inClip });
    console.log(`${c.out}  ${Number(dur).toFixed(2)} s`);
    inClip.forEach((m) => console.log(`   ${m.s.toFixed(1).padStart(5)} s  ${m.label}`));
  }
  const rp = path.join(ROOT, "_tools", `report-${take}.json`);
  fs.writeFileSync(rp, JSON.stringify(report, null, 1));
  return report;
}

if (process.argv[2]) {
  // node encode.mjs <take> '<clips json>'
  encode(process.argv[2], JSON.parse(process.argv[3]));
}

