// Take "cn": one continuous China / 5 Series session, cut into rec-01 … rec-05.
// Run from _tools with the app on :3000:  node take-cn.mjs
import { encode } from "./encode.mjs";
import { BASE, Human, Recorder, launch, sleep, still } from "./lib.mjs";

const FRIDGE = "Rear-seat refrigerator";
const PARKING = "Smaller footprint for city parking";
const REASON = "Contradicts L1: rear space is core for China";
const MORE_KEEPS = ["Extended rear legroom (long wheelbase)", "Quiet cabin / acoustic glass", "Rear entertainment screen"];

const { browser, page } = await launch({ clear: true });
const h = new Human(page);
const rec = new Recorder(page, "cn");
const row = (t) => page.locator("li[data-req]", { hasText: t }).first();

try {
  await page.goto(`${BASE}/dashboard/new`);
  await page.mouse.move(h.x, h.y);
  await page.waitForSelector("canvas", { timeout: 20000 });
  await sleep(3500); // globe fades in
  await rec.start();

  /* ---------- rec-01: L1 · market → series → pipeline ---------- */
  rec.mark("rec01:start");
  await sleep(900);
  await h.moveTo(1000, 560, 900); // drift over the globe
  await sleep(400);
  const china = page.getByRole("button", { name: /China/ }).first();
  await h.click(china, { pause: 650 });
  rec.mark("China selected");
  await sleep(900);
  await h.click(page.getByRole("link", { name: /Continue to China/ }), { pause: 600 });
  await page.waitForURL(/\/dashboard\/cn$/);
  rec.mark("Series picker (China · step 2 of 3)");
  await sleep(1200);
  const card = page.locator('a[href="/dashboard/cn/5-series"]');
  await h.hover(card, { dy: -60 });
  await sleep(700);
  await h.click(card.getByText("Start analysis"), { pause: 600 });
  await page.waitForURL(/\/dashboard\/cn\/5-series/);
  rec.mark("Pipeline opens: AI analysis, 'BMW principles' step first");
  await h.moveTo(1500, 760, 900);
  await page.getByText("Feature requests").first().waitFor({ timeout: 20000 });
  rec.mark("Analysis done: request list appears");
  await sleep(1600);
  rec.mark("rec01:end");

  /* ---------- rec-02: L2 · list → fridge detail ---------- */
  rec.mark("rec02:start");
  await sleep(500);
  await still(page, "cn-list.png");
  await h.hover(row(FRIDGE).getByRole("heading"), { ms: 900 });
  await sleep(500);
  await h.scrollTo(560, 1600);
  rec.mark("Scrolled to the scored request list");
  await sleep(900);
  await h.moveTo(470, 640, 700);
  await h.scrollBy(380, 1500);
  await sleep(700);
  await h.scrollBy(-380, 1400);
  await sleep(500);
  const fridgeInfo = page.getByRole("button", { name: `Details: ${FRIDGE}` });
  await h.click(fridgeInfo, { pause: 800 });
  rec.mark("Fridge detail panel opens");
  await sleep(1200);
  await h.moveTo(1700, 760, 900); // drift down to the quotes
  rec.mark("Quotes + channels visible");
  await sleep(1500);
  await still(page, "cn-fridge-detail.png");
  await sleep(1800);
  rec.mark("rec02:end");
  await h.click(page.locator("dialog[open]").getByRole("button", { name: "Close" }), { pause: 500 });
  await sleep(500);

  /* ---------- rec-03: decide · keep fridge, reject parking ---------- */
  rec.mark("rec03:start");
  await sleep(600);
  await h.click(page.getByRole("button", { name: `Keep: ${FRIDGE}` }), { pause: 800 });
  rec.mark("Kept: Rear-seat refrigerator");
  await sleep(1100);
  const rejectBtn = page.getByRole("button", { name: `Reject: ${PARKING}` });
  await h.ensureVisible(rejectBtn);
  await h.hover(row(PARKING).getByRole("heading"), { ms: 800 });
  await sleep(600);
  await h.click(rejectBtn, { pause: 700 });
  await page.locator("dialog[open] textarea").waitFor();
  rec.mark("Reject dialog opens");
  await sleep(700);
  await h.hover(page.locator("dialog[open] textarea"), { ms: 600 });
  await sleep(200);
  await h.type(REASON);
  rec.mark("Reason typed");
  await sleep(600);
  await still(page, "cn-reject-dialog.png");
  await h.click(page.getByRole("button", { name: "Reject and save reason" }), { pause: 700 });
  rec.mark("Reject confirmed: logged in Decisions");
  await sleep(700);
  await h.hover(page.locator("aside").getByText("Decisions").first(), { ms: 900 });
  await sleep(500);
  await h.moveTo(1460, 610, 800);
  await sleep(1500);
  await still(page, "decision-log.png");
  await sleep(900);
  rec.mark("rec03:end");

  /* ---------- rec-04: L3 · build profiles ---------- */
  rec.mark("rec04:start");
  await sleep(300);
  for (const t of MORE_KEEPS) {
    await h.click(page.getByRole("button", { name: `Keep: ${t}` }), { pause: 420, after: 250 });
  }
  rec.mark("Kept 3 more (legroom, quiet cabin, rear screen): 4 kept");
  await sleep(500);
  await h.click(page.getByRole("button", { name: "Build profiles" }), { pause: 700 });
  rec.mark("Build profiles clicked");
  await page.waitForURL(/generations#/, { timeout: 15000 });
  await page.getByText("Open profile").first().waitFor();
  rec.mark("Three profiles appear");
  await sleep(1000);
  const cards = page.locator("ul li button:has(h3)");
  for (let i = 0; i < 3; i++) {
    await h.hover(cards.nth(i), { dy: 40, ms: 700 });
    await sleep(650);
  }
  await still(page, "cn-profiles.png");
  const best = cards.first();
  const bestName = (await best.locator("h3").innerText()).trim();
  await h.click(best.getByText("Open profile"), { pause: 600 });
  rec.mark(`Opened profile: ${bestName}`);
  await sleep(1400);
  const why = page.getByText("Why this profile").first();
  const wy = await why.evaluate((el) => el.getBoundingClientRect().top + window.scrollY);
  await h.scrollTo(wy - 160, 2200);
  rec.mark("'Why this profile' + Principles");
  await h.moveTo(760, 560, 900);
  await sleep(2400);
  rec.mark("rec04:end");

  /* ---------- rec-05: L3 · social test ---------- */
  await h.scrollTo(0, 1100);
  await sleep(300);
  rec.mark("rec05:start");
  await sleep(400);
  await h.click(page.getByRole("button", { name: /Analytics/ }).first(), { pause: 600 });
  rec.mark("Analytics tab");
  await sleep(900);
  await h.click(page.getByRole("button", { name: "Launch test (simulated)" }), { pause: 700 });
  rec.mark("Social test launched: posts + scores");
  await sleep(1300);
  const leader = (await page.getByText("Tracking best · social score").locator("xpath=following-sibling::p[1]").innerText()).replace(/\s+/g, " ");
  rec.mark(`Leader: ${leader}`);
  await h.moveTo(900, 470, 800);
  await sleep(900);
  const chart = page.getByText("Engagement rate per day").first();
  const cy = await chart.evaluate((el) => el.getBoundingClientRect().top + window.scrollY);
  await h.scrollTo(cy - 200, 2200);
  rec.mark("Engagement curves");
  await h.moveTo(1000, 600, 700);
  await sleep(1800);
  await h.scrollTo(0, 1400);
  await page.getByRole("button", { name: /Profiles/ }).first().waitFor();
  await h.click(page.getByRole("button", { name: /Profiles/ }).first(), { pause: 500 });
  rec.mark("Profiles re-ranked with social score");
  await sleep(2200);
  rec.mark("rec05:end");
  const order = (await page.locator("ul li button:has(h3) h3").allInnerTexts()).join(" > ");
  console.log("  profile order after social:", order);
  await rec.stop();
} catch (e) {
  console.error("TAKE FAILED:", e);
  await page.screenshot({ path: "fail-cn.png" });
  await rec.stop().catch(() => {});
  await browser.close();
  process.exit(1);
}
await browser.close();

encode("cn", [
  { out: "rec-01-l1.mp4", from: "rec01:start", to: "rec01:end" },
  { out: "rec-02-l2-list.mp4", from: "rec02:start", to: "rec02:end" },
  { out: "rec-03-l2-decide.mp4", from: "rec03:start", to: "rec03:end" },
  { out: "rec-04-l3-profiles.mp4", from: "rec04:start", to: "rec04:end" },
  { out: "rec-05-l3-social.mp4", from: "rec05:start", to: "rec05:end" },
]);

