// Take "weights": /dashboard/settings → nudge a slider → "Tell Dixi in your words" → proposal → Apply → change log.
// Long AI waits are shortened in the cut (the "Thinking…" stretch is trimmed to ~1.5 s, noted in RECORDINGS.md).
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { encode } from "./encode.mjs";
import { BASE, Human, ROOT, Recorder, launch, sleep, still } from "./lib.mjs";

const PROMPT = "Trust customer feedback more than social media for the 5 Series";
const { browser, page } = await launch({ clear: true });
const h = new Human(page);
const rec = new Recorder(page, "weights");
let waited = 0;
let proposal = "";

try {
  await page.goto(`${BASE}/dashboard/settings`);
  await page.mouse.move(h.x, h.y);
  await page.getByText("Tell Dixi in your words").waitFor();
  await sleep(1200);
  await rec.start();
  rec.mark("rec06:start");
  await sleep(500);

  // nudge the Demand weight slider: 60 → 70
  const slider = page.locator('input[type="range"]').first();
  const b = await h.box(slider);
  const xAt = (v) => b.x + 8 + (b.width - 16) * v;
  await h.moveTo(xAt(0.6), b.y + b.height / 2, 900);
  await sleep(500);
  await page.mouse.down();
  rec.mark("Drag Demand weight slider");
  for (let i = 1; i <= 24; i++) {
    await page.mouse.move(xAt(0.6 + (0.1 * i) / 24), b.y + b.height / 2);
    await sleep(28);
  }
  h.x = xAt(0.7);
  await page.mouse.up();
  rec.mark("Demand weight nudged 60 → 70");
  await sleep(900);

  const box = page.getByLabel("Instruction for the scoring");
  await h.click(box, { pause: 500, after: 150 });
  rec.mark("Typing instruction");
  await h.type(PROMPT);
  await sleep(500);
  await h.click(page.getByRole("button", { name: "Suggest settings" }), { pause: 500, after: 0 });
  rec.mark("thinking");
  const t = Date.now();
  await page.getByText(/^Proposal ·/).waitFor({ timeout: 90000 });
  waited = (Date.now() - t) / 1000;
  rec.mark("Proposal shown");
  proposal = (await page.locator('[aria-live="polite"]').filter({ hasText: "Proposal" }).innerText()).replace(/\n+/g, " | ");
  console.log("  proposal:", proposal, `(waited ${waited.toFixed(1)} s)`);
  await h.moveTo(1240, 640, 800);
  await sleep(2400);
  await still(page, "weights.png");
  const apply = page.getByRole("button", { name: "Apply" });
  if (await apply.isDisabled()) throw new Error("Apply disabled: proposal changes nothing");
  await h.click(apply, { pause: 700 });
  rec.mark("Applied: change logged");
  await sleep(600);
  await h.hover(page.getByText("Change log"), { ms: 700 });
  await sleep(1800);
  await still(page, "weights-logged.png");
  rec.mark("rec06:end");
  await rec.stop();
} catch (e) {
  console.error("TAKE FAILED:", e);
  await page.screenshot({ path: "fail-weights.png" });
  await rec.stop().catch(() => {});
  await browser.close();
  process.exit(1);
}
await browser.close();

if (waited > 3) {
  encode("weights", [
    { out: "_part-06a.mp4", from: "rec06:start", to: "thinking", post: 1.5 },
    { out: "_part-06b.mp4", from: "Proposal shown", to: "rec06:end", pre: 0.4 },
  ]);
  const list = path.join(ROOT, "_frames", "weights", "parts.txt");
  fs.writeFileSync(list, `file '${path.join(ROOT, "_part-06a.mp4")}'\nfile '${path.join(ROOT, "_part-06b.mp4")}'\n`);
  execFileSync("ffmpeg", ["-y", "-loglevel", "error", "-f", "concat", "-safe", "0", "-i", list, "-c", "copy", "-movflags", "+faststart", path.join(ROOT, "rec-06-weights.mp4")], { stdio: "inherit" });
  fs.rmSync(path.join(ROOT, "_part-06a.mp4"));
  fs.rmSync(path.join(ROOT, "_part-06b.mp4"));
  console.log(`rec-06-weights.mp4 (AI wait ${waited.toFixed(1)} s trimmed to 1.9 s)`);
} else {
  encode("weights", [{ out: "rec-06-weights.mp4", from: "rec06:start", to: "rec06:end" }]);
}
fs.writeFileSync(path.join(ROOT, "_tools", "weights-meta.json"), JSON.stringify({ waited, proposal }, null, 1));

