// Take "us": USA / 5 Series, keep the top four (driver-side) requests, build profiles. Fresh storage.
import { encode } from "./encode.mjs";
import { BASE, Human, Recorder, launch, sleep, still } from "./lib.mjs";

const KEEPS = ["Sharper steering / driver focus", "Wireless CarPlay stability", "Head-up display", "Ventilated front seats"];
const { browser, page } = await launch({ clear: true });
const h = new Human(page);
const rec = new Recorder(page, "us");

try {
  await page.goto(`${BASE}/dashboard/us/5-series`);
  await page.getByRole("button", { name: "Skip" }).click();
  await page.getByText("Feature requests").first().waitFor();
  await page.mouse.move(h.x, h.y);
  await sleep(800);
  const top = (await page.locator("li[data-req] h3").allInnerTexts()).slice(0, 6);
  console.log("  US top:", top.join(" | "));
  await rec.start();
  rec.mark("rec07:start");
  await sleep(500);
  for (const [i, t] of KEEPS.entries()) {
    await h.click(page.getByRole("button", { name: `Keep: ${t}` }), { pause: i === 0 ? 650 : 300, after: 150 });
    if (i === 0) rec.mark(`Kept top request: ${t}`);
  }
  rec.mark("4 kept");
  await sleep(200);
  await h.click(page.getByRole("button", { name: "Build profiles" }), { pause: 450 });
  rec.mark("Build profiles clicked");
  await page.waitForURL(/generations#/, { timeout: 15000 });
  await page.getByText("Open profile").first().waitFor();
  rec.mark("US profiles appear");
  const cards = page.locator("ul li button:has(h3)");
  await h.hover(cards.first(), { dy: 60, ms: 700 });
  await sleep(1600);
  await still(page, "us-profiles.png");
  await sleep(600);
  rec.mark("rec07:end");
  const names = await page.locator("ul li button:has(h3) h3").allInnerTexts();
  console.log("  US profile order:", names.join(" > "));
  await rec.stop();
} catch (e) {
  console.error("TAKE FAILED:", e);
  await page.screenshot({ path: "fail-us.png" });
  await rec.stop().catch(() => {});
  await browser.close();
  process.exit(1);
}
await browser.close();
encode("us", [{ out: "rec-07-us-profiles.mp4", from: "rec07:start", to: "rec07:end" }]);

